                       if len({grid[r][c] for r in range(h)}) == 1)
        source = [row[:sep_col] for row in grid]
        target = [row[sep_col + 1:] for row in grid]

    counts = {}
    for row in source:
        for color in row:
            counts[color] = counts.get(color, 0) + 1
    source_background = max(counts, key=counts.get)

    shared = set(counts)
    for row in target:
        shared.intersection_update(row)

    return [[3 if color in shared else source_background for color in row]
